  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --bg-accent: #11182b;
      --panel: #161f35;
      --panel-strong: #1d2945;
      --text: #f3f7ff;
      --muted: #b8c4e0;
      --border: #30405f;
      --accent: #88b4ff;
      --accent-strong: #a9c8ff;
      --shadow: 0 18px 45px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(136, 180, 255, 0.16), transparent 32%),
        linear-gradient(180deg, var(--bg) 0%, #070b16 100%);
      color: var(--text);
      line-height: 1.6;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-220%);
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: var(--accent);
      color: #08101f;
      font-weight: 700;
      text-decoration: none;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 2px solid var(--text);
      outline-offset: 2px;
    }

    main {
      width: min(100%, 56rem);
      margin: 0 auto;
      padding: 4rem 1.25rem;
    }

    .hero {
      padding: 2rem 0 1rem;
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(2.25rem, 4vw, 3.5rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .intro {
      max-width: 42rem;
      margin: 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .faq-list {
      display: grid;
      gap: 1rem;
      margin-top: 2rem;
    }

    .example {
      background: linear-gradient(180deg, rgba(29, 41, 69, 0.92), rgba(18, 27, 47, 0.96));
      border: 1px solid var(--border);
      border-radius: 1rem;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .question {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1.2rem 1.25rem;
      border: 0;
      background: transparent;
      color: var(--text);
      text-align: left;
      font: inherit;
      font-size: 1.05rem;
      font-weight: 700;
      cursor: pointer;
    }

    .question:hover {
      background: rgba(255, 255, 255, 0.03);
    }

    .question:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: -3px;
    }

    .chevron {
      flex: 0 0 auto;
      width: 1rem;
      height: 1rem;
      border-right: 2px solid currentColor;
      border-bottom: 2px solid currentColor;
      transform: rotate(45deg);
      transition: transform 0.2s ease;
      color: var(--accent-strong);
      margin-right: 0.35rem;
    }

    .question[aria-expanded="true"] .chevron {
      transform: rotate(225deg);
    }

    .details {
      padding: 0 1.25rem 1.25rem;
      color: var(--muted);
    }

    .details p {
      margin: 0;
    }

    @media (max-width: 40rem) {
      main {
        padding: 3rem 1rem;
      }

      .question {
        align-items: flex-start;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
        color: CanvasText;
